import{_ as n,C as a,o as i,c as o,E as s,a2 as r}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"CodeFlowMu Digital Employee Production Machine Architecture V0.3.1 (Draft)","description":"","frontmatter":{"title":"CodeFlowMu Digital Employee Production Machine Architecture V0.3.1 (Draft)","outline":"deep"},"headers":[],"relativePath":"en/digital-employee/architecture.md","filePath":"en/digital-employee/architecture.md","lastUpdated":1786702168000}'),l={name:"en/digital-employee/architecture.md"};function d(c,e,p,u,h,m){const t=a("ArticleCover");return i(),o("div",null,[s(t,{image:"/assets/covers/digital-employee.svg",kicker:"Public Architecture Draft",title:"CodeFlowMu Digital Employee Production Machine Architecture V0.3.1",summary:"A configurable, recoverable and verifiable Digital Employee production architecture built on one CodeFlowMu canonical Runtime, with versioned position definitions, controlled deployment, FCoP durable facts, TMPA deterministic reconstruction, fact-checking and independent EVAL observation.",version:"V0.3.1 Draft",status:"Public draft · non-normative",languageHref:"/zh/digital-employee/architecture",languageLabel:"简体中文"}),e[0]||(e[0]=r(`<blockquote><p><strong>Document status:</strong> This is a public architecture draft for discussion and engineering implementation. It is not part of TMPA Core S1.0 and does not claim that all target capabilities below are already present in the public CodeFlowMu product. “Running baseline” and “target capability” must remain distinct.</p></blockquote><h2 id="conclusion-first" tabindex="-1">Conclusion first <a class="header-anchor" href="#conclusion-first" aria-label="Permalink to &quot;Conclusion first&quot;">​</a></h2><p>CodeFlowMu already operates as a <strong>software-development Digital Employee</strong>: externally it performs a software-development position; internally PM, DEV, QA and OPS collaborate, EVAL observes independently, and ADMIN retains final governance authority.</p><p>The next step is not to copy CodeFlowMu and create a separate “application Runtime,” nor to place more agents inside a hard-coded flow. The intended path is to:</p><ol><li>preserve the current canonical Runtime, FCoP, TMPA Reader, fact-checking, recovery and approval chain;</li><li>add Digital Employee definition, validation, compilation, deployment and activation above that same kernel;</li><li>describe the current development team as the first configurable instance and prove behavioral equivalence in shadow mode;</li><li>produce a structurally different, non-development reference instance without modifying Core;</li><li>promote draft capabilities to product facts only after gates, controlled cutover and rollback evidence.</li></ol><p>The central statement is:</p><blockquote><p><strong>CodeFlowMu is the track machine; agents supply intelligence. A Digital Employee appears externally as one position and operates internally as a multi-role team organized by a persistent PM authority identity.</strong></p></blockquote><h2 id="a-digital-employee-is-not-an-agent" tabindex="-1">A Digital Employee is not an agent <a class="header-anchor" href="#a-digital-employee-is-not-an-agent" aria-label="Permalink to &quot;A Digital Employee is not an agent&quot;">​</a></h2><p>A Digital Employee is a persistent, software-defined organizational work unit accountable for a bounded class of outcomes.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Digital Employee</span></span>
<span class="line"><span>├── External contract: Position</span></span>
<span class="line"><span>├── Internal governance: persistent PM authority identity</span></span>
<span class="line"><span>├── Internal execution: managed multi-role team</span></span>
<span class="line"><span>└── Runtime foundation: CodeFlowMu</span></span></code></pre></div><p>A model, prompt, Agent session, workflow, script, avatar or tool is only an implementation component. None alone defines a Digital Employee.</p><p>A stable position contract includes at least:</p><ul><li>position purpose, responsibility and Work Catalog;</li><li>role whitelist and separation of duties;</li><li>allowed and prohibited work;</li><li>capability, data, network and credential boundaries;</li><li>AcceptanceContract and evidence requirements;</li><li>fact-checking, independent verification and human-authority boundaries;</li><li>scheduling, reporting, cost, recovery and lifecycle policies.</li></ul><p>Models, providers, hosts, sessions, temporary workers and tools may change. The position definition, responsibility chain and durable facts must survive those changes.</p><h2 id="one-kernel-not-two-runtimes" tabindex="-1">One kernel, not two Runtimes <a class="header-anchor" href="#one-kernel-not-two-runtimes" aria-label="Permalink to &quot;One kernel, not two Runtimes&quot;">​</a></h2><p><strong>CodeFlowMu is the Digital Employee Runtime.</strong> Cursor, Codex, OpenHands, model APIs and local models are replaceable providers, hosts or adapters.</p><p>A development Digital Employee and a business Digital Employee are not separate runtimes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>One CodeFlowMu canonical Runtime</span></span>
<span class="line"><span>├── Development Digital Employee instance</span></span>
<span class="line"><span>├── Research-publication Digital Employee instance</span></span>
<span class="line"><span>└── Other enterprise position instances</span></span></code></pre></div><p>Differences belong in <code>EmployeeDefinitionVersion</code>, <code>DeploymentRevision</code>, roles, skills, policies, Work Catalogs and external-system bindings—not in duplicated Core implementations.</p><p>The Digital Employee upgrade adds a <strong>configurable definition and deployment layer</strong>. It must not add:</p><ul><li>a second TASK, REPORT, REVIEW or ISSUE system;</li><li>a second source of runtime truth;</li><li>a second governance-decision outlet;</li><li>an audit database parallel to Evidence Snapshot;</li><li>a hidden lifecycle controlled by EVAL or UI.</li></ul><h2 id="five-layer-architecture" tabindex="-1">Five-layer architecture <a class="header-anchor" href="#five-layer-architecture" aria-label="Permalink to &quot;Five-layer architecture&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Authoritative content</th><th>Explicit non-responsibility</th></tr></thead><tbody><tr><td>FCoP reality protocol</td><td>TASK, REPORT, REVIEW, ISSUE, lifecycle, relationships and evidence ownership</td><td>Agent scheduling, model selection, business workflows</td></tr><tr><td>TMPA Reader governance</td><td>Asynchronous deterministic reconstruction over visible facts, retaining gaps, disputes and partial order</td><td>Writing FCoP facts or accepting work for PM/ADMIN</td></tr><tr><td>CodeFlowMu Runtime</td><td>Session, Run, attempt, lease, Host, Switchboard, gates, recovery and canonical snapshot</td><td>Hard-coding an industry position or workflow</td></tr><tr><td>Digital Employee definition and deployment</td><td>Position, team, responsibility, skills, capabilities, negative lists, acceptance, reporting and trigger policies</td><td>Creating a second fact, task or lifecycle system</td></tr><tr><td>Digital Employee instance</td><td>One real position running in one project and deployment</td><td>Redefining or contaminating generic Core</td></tr></tbody></table><p>The layers cooperate through an asynchronous fact-reconstruction loop. They are not a synchronous pipeline that requires every agent to remain online.</p><h2 id="core-objects-and-fact-ownership" tabindex="-1">Core objects and fact ownership <a class="header-anchor" href="#core-objects-and-fact-ownership" aria-label="Permalink to &quot;Core objects and fact ownership&quot;">​</a></h2><h3 id="definition-deployment-and-activation" tabindex="-1">Definition, deployment and activation <a class="header-anchor" href="#definition-deployment-and-activation" aria-label="Permalink to &quot;Definition, deployment and activation&quot;">​</a></h3><ul><li><code>EmployeeDefinitionVersion</code>: an immutable, addressable position definition describing what the employee is, what it may do and what counts as completion.</li><li><code>DeploymentRevision</code>: binds a definition to workers, hosts, providers, projects, schedulers and capability grants.</li><li><code>DefinitionApprovalReceipt</code>: records ADMIN approval of the definition and its authority boundary.</li><li><code>ActivationReceipt</code>: records that a deployment revision may run in shadow or active mode.</li><li><code>SecurityPolicyOverrideReceipt</code>: may only monotonically tighten a live security boundary; it cannot expand authority as a “hotfix.”</li></ul><p>These receipts are evidence of governance actions. They are not a new state machine and cannot independently declare a TASK done or archived.</p><h3 id="work-and-execution" tabindex="-1">Work and execution <a class="header-anchor" href="#work-and-execution" aria-label="Permalink to &quot;Work and execution&quot;">​</a></h3><ul><li>A formal <code>WorkOrder</code> is carried by an <strong>FCoP TASK</strong>; no parallel WorkOrder database is introduced.</li><li>One TASK may have multiple <code>Run</code> records. Rework, recovery, host migration and retries retain their own session/run/attempt/lease identity.</li><li><code>WorkContextCapsule</code> is a read-only input compiled by the track machine for one Session, binding task, definition, deployment, prompt, skills, tools, policies, fact snapshot and gates.</li><li><code>ReportEnvelope</code> is the structured entry to a formal REPORT. It cannot overwrite the source object when it conflicts with durable facts.</li></ul><h2 id="persistent-pm-bounded-sessions" tabindex="-1">Persistent PM, bounded Sessions <a class="header-anchor" href="#persistent-pm-bounded-sessions" aria-label="Permalink to &quot;Persistent PM, bounded Sessions&quot;">​</a></h2><p>PM is a <strong>persistent logical authority identity</strong>, not an LLM Session that never exits.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FCoP durable facts + canonical snapshot</span></span>
<span class="line"><span>→ track machine compiles WorkContextCapsule</span></span>
<span class="line"><span>→ PM Session N performs one bounded turn of work</span></span>
<span class="line"><span>→ new formal facts are appended</span></span>
<span class="line"><span>→ Reader reconstructs deterministically</span></span>
<span class="line"><span>→ PM Session N+1 continues</span></span></code></pre></div><p>Therefore:</p><ul><li>Sessions may end, compact, recover or move to another Host;</li><li>PM position identity, responsibility and decision attribution remain continuous;</li><li>concurrent Sessions require non-conflicting task-local leases;</li><li>sub-agents produce advisory outputs by default and cannot silently acquire PM, FCoP or privileged tool authority;</li><li>the track machine assembles order, context, skills, tool surface and gates instead of entrusting state to model memory.</li></ul><h2 id="ai-native-workflow-and-execution-safety" tabindex="-1">AI-native workflow and execution safety <a class="header-anchor" href="#ai-native-workflow-and-execution-safety" aria-label="Permalink to &quot;AI-native workflow and execution safety&quot;">​</a></h2><p>A Digital Employee must avoid two extremes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Everything hard-coded → degenerates into RPA</span></span>
<span class="line"><span>Only a goal prompt → degenerates into an uncontrolled agent</span></span></code></pre></div><p>The intended middle ground keeps position, responsibility, authority, state and completion contracts stable; allows AI to plan within those boundaries; executes deterministic rules in programs; retains reconstructable evidence; and supports recovery, review and human gates.</p><p>Every execution role is constrained by two layers:</p><ol><li><strong>Capability Envelope / Sandbox Boundary:</strong> default-deny limits over tools, paths, network, credentials, resources and side effects.</li><li><strong>Negative List / Contextual Business Rule:</strong> behavior that may be technically possible but remains prohibited for this position and task.</li></ol><p>Semantic quality requirements belong in AcceptanceContract or quality gates, not in permission controls. Replacing a model cannot compensate for missing responsibility, evidence or safety boundaries.</p><h2 id="facts-evidence-observation-and-decisions" tabindex="-1">Facts, evidence, observation and decisions <a class="header-anchor" href="#facts-evidence-observation-and-decisions" aria-label="Permalink to &quot;Facts, evidence, observation and decisions&quot;">​</a></h2><p>A Digital Employee separates four mechanisms:</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Primary executor</th><th>Product</th><th>Final business-decision authority</th></tr></thead><tbody><tr><td>Deterministic fact-checking</td><td>CodeFlowMu program and registered fact sources</td><td>Match, gap, conflict, staleness and evidence chain</td><td>None</td></tr><tr><td>Agent execution or research</td><td>Specialist role agents</td><td>REPORT, deliverables, citations and tool evidence</td><td>None</td></tr><tr><td>Independent verification / EVAL</td><td>Independent agent or verifier</td><td>Counterevidence, structural risk and observation</td><td>None</td></tr><tr><td>Business acceptance</td><td>PM or ADMIN</td><td>approve, reject, rework, done, archive</td><td>Yes, within formal authority</td></tr></tbody></table><p>The existing production chain remains intact:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Action Evidence</span></span>
<span class="line"><span>→ Execution Provenance</span></span>
<span class="line"><span>→ ReviewEvidenceResolver / Evidence Snapshot</span></span>
<span class="line"><span>→ AcceptanceContract + ReviewFactGate</span></span>
<span class="line"><span>→ fact-check REVIEW (observation only)</span></span>
<span class="line"><span>→ PM / ADMIN business decision</span></span></code></pre></div><p><code>GovernanceFactKernel</code> remains the canonical projection kernel for governance facts, with <code>business_decision</code> unset. The sole production-state outlet is not delegated to a Panel, EVAL or any agent.</p><p>A Runtime process ending, a tool returning success or an agent saying “done” cannot independently prove business completion. Formal completion is evaluated per applicable AcceptanceContract, evidence, FCoP lifecycle, independent acceptance and human authority. <code>publication_state</code> applies only to work types that actually publish; it is not a universal completion condition.</p><h2 id="evidence-lineage-a-horizontal-enhancement-inside-one-snapshot" tabindex="-1">Evidence Lineage: a horizontal enhancement inside one snapshot <a class="header-anchor" href="#evidence-lineage-a-horizontal-enhancement-inside-one-snapshot" aria-label="Permalink to &quot;Evidence Lineage: a horizontal enhancement inside one snapshot&quot;">​</a></h2><p>V0.3.1 proposes an optional <code>EvidenceLineageProjection</code> inside the existing Evidence Snapshot. It is not a separate “decision-dependency audit layer”; it is a disposable, deterministically rebuildable projection of the same evidence snapshot.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Execution layer: what the agent did</span></span>
<span class="line"><span>Dependency layer: which actions, resource versions, claims and acceptance items support the current conclusion</span></span></code></pre></div><p>The intended upgrade is:</p><blockquote><p><strong>Fact-checking moves from “does evidence exist?” to “does the evidence chain support the current conclusion?” EVAL moves from “is the summary complete?” to “are the dependency structure and systemic risk reasonable?”</strong></p></blockquote><p>Dependency sources are classified as:</p><ul><li><code>observed</code>: directly captured at Action Evidence and tool boundaries with immutable resource versions;</li><li><code>declared</code>: stated by AcceptanceContract or formal REPORT and checked against actual nodes;</li><li><code>inferred</code>: derived from rules or graph structure, usable for EVAL risk observation but never sufficient alone for deterministic failure or approval.</li></ul><p>Fact-checking and EVAL must consume the same Evidence Snapshot, <code>TargetStateManifest</code>, typed graph, complete <code>findings[]</code> and graph digest. <code>summary_state</code> is an overview only. Conflict, staleness and gaps may coexist and must not be erased by one summary value.</p><p>Target resource scope comes only from explicit bounded selectors in the compiled AcceptanceContract. EVAL, Panel, Builder and REPORT authors cannot expand or shrink it ad hoc, and the system cannot fall back to scanning the whole workspace.</p><h3 id="fact-check-boundary" tabindex="-1">Fact-check boundary <a class="header-anchor" href="#fact-check-boundary" aria-label="Permalink to &quot;Fact-check boundary&quot;">​</a></h3><p>Fact-checking evaluates each acceptance item as:</p><ul><li><code>verified</code>: the deterministic evidence chain is complete;</li><li><code>gap</code>: an execution version, supporting event or intermediate relationship is missing;</li><li><code>conflict</code>: hard sources disagree or graph integrity fails;</li><li><code>stale</code>: the target resource changed after evidence was produced;</li><li><code>not_applicable</code>: the contract explicitly excludes resource-level dependency verification.</li></ul><p>These states explain evidence. They do not automatically approve or reject the business result.</p><h3 id="eval-boundary" tabindex="-1">EVAL boundary <a class="header-anchor" href="#eval-boundary" aria-label="Permalink to &quot;EVAL boundary&quot;">​</a></h3><p>EVAL may observe:</p><ul><li>dependency completeness;</li><li>downstream impact of a failure or gap;</li><li>critical evidence nodes;</li><li>nearest deterministic and probable breakpoints;</li><li>cross-role and cross-report structural risk.</li></ul><p>EVAL remains <code>internal_only</code> and <code>drives_lifecycle: false</code>. Only a registered critical rule followed by hard-evidence verification may escalate through the existing ISSUE / governance-hold path. Graph ranking, risk scores, inferred edges and summary state have no blocking authority by themselves.</p><p>CodeFlowMu will implement this capability independently in TypeScript, without an external Python runtime or second decision system. The execution/dependency dual representation, source classification and basic graph analysis are design references to <a href="https://github.com/yzhao062/grade/tree/3839a57ac165d58a807fce0a3ff38346732ee936" target="_blank" rel="noreferrer">GRADE</a> and <a href="https://github.com/yzhao062/auditable/tree/v0.2.0" target="_blank" rel="noreferrer">auditable v0.2.0</a>; their performance claims are not inherited.</p><h2 id="skills-knowledge-and-governed-learning" tabindex="-1">Skills, Knowledge and governed learning <a class="header-anchor" href="#skills-knowledge-and-governed-learning" aria-label="Permalink to &quot;Skills, Knowledge and governed learning&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Object</th><th>Purpose</th></tr></thead><tbody><tr><td>Position</td><td>Long-term responsibility and accountability</td></tr><tr><td>Work Skill</td><td>Stable method and delivery constraints for one role and work class</td></tr><tr><td>Method Skill</td><td>Reusable analysis, writing, testing and verification method</td></tr><tr><td>Tool Capability</td><td>An ability type that may be requested; actual grants remain bounded by Capability Envelope</td></tr><tr><td>Knowledge</td><td>Business facts, rules, terms, pages and system knowledge</td></tr><tr><td>Policy</td><td>Authority, capability, negative-list, evidence and acceptance boundaries</td></tr><tr><td>Prompt</td><td>A short-lived projection compiled for one TASK from the objects above</td></tr></tbody></table><p>Experience from one Run cannot directly overwrite formal Skills, Knowledge, Workflows or Policies:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run / Failure / EVAL</span></span>
<span class="line"><span>→ Candidate</span></span>
<span class="line"><span>→ independent review and safe-data regression</span></span>
<span class="line"><span>→ versioned approval</span></span>
<span class="line"><span>→ governed Skill / Knowledge / Workflow / Policy</span></span></code></pre></div><h2 id="running-foundation-and-target-capabilities" tabindex="-1">Running foundation and target capabilities <a class="header-anchor" href="#running-foundation-and-target-capabilities" aria-label="Permalink to &quot;Running foundation and target capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Current public assessment</th></tr></thead><tbody><tr><td>FCoP TASK/REPORT/REVIEW/ISSUE, current development team, Session/Run/recovery, fact-checking and EVAL chain</td><td>Supported by running and engineering evidence, bounded to exact versions and evidence packages</td></tr><tr><td>Governance Fact Kernel, Evidence Snapshot, AcceptanceContract and ReviewFactGate</td><td>Observed in the private product line; not public source or proof of general correctness</td></tr><tr><td>Generic EmployeeDefinition, Deployment, Activation and definition-driven Context Capsule</td><td>V0.3.1 target capability requiring implementation and gates</td></tr><tr><td>Evidence Lineage, TargetStateManifest, resource-version staleness and graph-structured EVAL</td><td>WP-14 target capability; not a current public-product claim</td></tr><tr><td>Cross-domain Digital Employee production machine</td><td>Must be demonstrated through development-team bootstrap and at least one non-development reference instance</td></tr></tbody></table><h2 id="bootstrap-and-engineering-proof" tabindex="-1">Bootstrap and engineering proof <a class="header-anchor" href="#bootstrap-and-engineering-proof" aria-label="Permalink to &quot;Bootstrap and engineering proof&quot;">​</a></h2><p>Credible bootstrap does not mean a live process rewrites itself:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pin a parent version and evidence</span></span>
<span class="line"><span>→ develop configurable capability on an isolated branch</span></span>
<span class="line"><span>→ describe and reproduce the current development team</span></span>
<span class="line"><span>→ shadow comparison</span></span>
<span class="line"><span>→ controlled cutover with rollback retained</span></span>
<span class="line"><span>→ new development Digital Employee builds a later version</span></span>
<span class="line"><span>→ produce a non-development reference instance</span></span></code></pre></div><p>The decisive proof is not “more agents.” It is:</p><blockquote><p><strong>The same CodeFlowMu Core can operate both a software-development Digital Employee and a structurally different business or research Digital Employee without encoding business-specific role order and workflow logic in Core.</strong></p></blockquote><p>The research-publication Digital Employee is the first candidate reference instance. A reference instance is not the generic engine itself.</p><h2 id="engineering-origin-and-public-boundary" tabindex="-1">Engineering origin and public boundary <a class="header-anchor" href="#engineering-origin-and-public-boundary" aria-label="Permalink to &quot;Engineering origin and public boundary&quot;">​</a></h2><p>The problem framing grew from engineering the Xiaodian AI enterprise application. One stream asked “who develops enterprise AI?” and led toward multi-role development, FCoP and CodeFlowMu. The other asked “how should enterprise AI enter business operations under governance?” and led toward TMPA and the Digital Employee architecture. The streams now meet again in the Digital Employee production machine.</p><p>The <a href="https://demo.chedian.cc" target="_blank" rel="noreferrer">Xiaodian AI PWA Demo</a> is now public for hands-on exploration; its source code and production systems remain private. The demo is a public experience entry point, not public evidence of TMPA S1.0 conformance, independent validation, production readiness or product generality.</p><h2 id="sme-first-economics" tabindex="-1">SME-first economics <a class="header-anchor" href="#sme-first-economics" aria-label="Permalink to &quot;SME-first economics&quot;">​</a></h2><p>Persistent does not mean an LLM consumes tokens continuously. Position, identity, authority, tasks, work history, state, evidence, deployment versions, evaluation and cost records persist. Compute activates when work arrives.</p><h2 id="implementation-path" tabindex="-1">Implementation path <a class="header-anchor" href="#implementation-path" aria-label="Permalink to &quot;Implementation path&quot;">​</a></h2><p>V0.3.1 separates engineering into fourteen work packages, grouped as:</p><ol><li>definition, identity, schemas and effective FCoP contract;</li><li>development-team self-description, role policy and separation of duties;</li><li>definition validation, deployment compilation, activation and Gate Registry;</li><li>WorkContextCapsule and prompt/skill/tool assembly;</li><li>asynchronous routing, PM continuity, Switchboard shadow and duplicate-delivery prevention;</li><li>default-deny tool boundaries, credential isolation and security hotfixes;</li><li>periodic reporting, research-publication reference instance and revision migration;</li><li>exclusive cutover, legacy-path retirement and rollback;</li><li>WP-14: Evidence Lineage enhancement for fact-checking and EVAL.</li></ol><p>Work packages remain governed through the current FCoP TASK/REPORT/REVIEW chain. This draft is not execution authority and cannot replace ADMIN definition approval, activation or cutover decisions.</p><h2 id="validation-still-required-after-this-draft" tabindex="-1">Validation still required after this draft <a class="header-anchor" href="#validation-still-required-after-this-draft" aria-label="Permalink to &quot;Validation still required after this draft&quot;">​</a></h2><ul><li>implementation-level freeze of generic definition and deployment schemas;</li><li>capability and tool enforcement across supported hosts and operating systems;</li><li>credential isolation, revocation and side-effect normalization;</li><li>PM backpressure, long-task-tree migration and successor Sessions;</li><li>Workflow/Knowledge promotion rules and regression datasets;</li><li>Evidence Lineage shadow compatibility, cross-platform determinism and scale limits;</li><li>behavioral-equivalence migration of the development Digital Employee;</li><li>complete non-development reference run without modifying Core;</li><li>active cutover, rollback and removal of legacy production authority.</li></ul><p>A target may be promoted from “architecture” to “implemented capability” only after its corresponding gates and evidence are complete.</p>`,91))])}const y=n(l,[["render",d]]);export{b as __pageData,y as default};
